def is_pow2(n):
    return (n & (n-1) == 0) and n > 0

def get_hadK(n, transpose=False):
    hadK, K = None, None
    if n % 172 == 0:
        assert is_pow2(n // 172)
        K = 172
        hadK = get_had172().T if transpose else get_had172()
    else:
        assert is_pow2(n)
        K = 1
    return hadK, K

def matmul_hadU(X, transpose=False):
    """QuIP# Hadamard transform (pure PyTorch, no CUDA kernel)"""
    n = X.shape[-1]
    hadK, K = get_hadK(n, transpose)
    input_ = X.clone().float().view(-1, n, 1)
    output = input_.clone()
    while input_.shape[1] > K:
        input_ = input_.view(input_.shape[0], input_.shape[1]//2, 2, input_.shape[2])
        output  = output.view(input_.shape)
        output[:,:,0,:] = input_[:,:,0,:] + input_[:,:,1,:]
        output[:,:,1,:] = input_[:,:,0,:] - input_[:,:,1,:]
        output  = output.view(input_.shape[0], input_.shape[1], -1)
        input_, output = output, input_
    if K > 1:
        hK = hadK.to(input_.device).float()
        input_ = torch.bmm(hK.unsqueeze(0).expand(len(input_),-1,-1), input_)
    return (input_.view(X.shape) / (n**0.5)).to(X.dtype)

def matmul_hadUt(X):
    return matmul_hadU(X, transpose=True)
